function nativeCoverBytes(request:Request){
 const headers=request.headers();expect(new URL(request.url()).origin).toBe(origin);expect(new URL(request.url()).pathname).toBe(`${base}/media`);expect(request.method()).toBe('POST');expect(headers['x-media-purpose']).toBe('collection');expect(headers['x-file-name']).toBe('cropped-image.jpg');expect(headers['content-type']).toBe('image/jpeg');const bytes=request.postDataBuffer();expect(bytes).not.toBeNull();expect(bytes!.length).toBeGreaterThan(4);expect(bytes!.length).toBeLessThanOrEqual(10*1024*1024);expect(bytes!.subarray(0,2)).toEqual(Buffer.from([255,216]));expect(bytes!.subarray(-2)).toEqual(Buffer.from([255,217]));return {bytes:Buffer.from(bytes!),byteLength:bytes!.length,sha256:createHash('sha256').update(bytes!).digest('hex')};
}
function assertCoverPersistedScope(before:Observation,after:Observation,collection:{id:string;revision:number;title:string;description:string|null},guide:GuideAggregateDto,uploaded?:{id:string;accountId:string;byteLength:number;sha256:string}){
 const target=before.guides.find(g=>g.id===collection.id)!;expect(target).toBeDefined();expect(collection.title).toBe(target.title);expect(collection.description).toBe(target.description);expect(after.guides.map(g=>g.id)).toEqual(before.guides.map(g=>g.id));expect(after.sections).toEqual(before.sections);
 for(const old of before.guides)expect(after.guides.find(g=>g.id===old.id)).toEqual({...old,...(old.id===target.id?{revision:collection.revision,title:collection.title,description:collection.description,details:guide.details}:{}),categoryContentRevision:old.accountId===target.accountId?guide.revision:old.categoryContentRevision});
 for(const [key,old] of Object.entries(before.personas))expect(after.personas[key]).toEqual({...old,guidesContentRevision:old.accountId===target.accountId?guide.revision:old.guidesContentRevision});
 if(!uploaded){for(const key of ['media','objects','attachments'] as const)expect(after[key]).toEqual(before[key]);return;}
 expect(uploaded.accountId).toBe(target.accountId);for(const key of ['media','objects'] as const){const idKey=key==='media'?'id':'mediaId';const rows=after[key] as Record<string,unknown>[];expect(rows.filter(row=>row[idKey]!==uploaded.id)).toEqual(before[key]);const added=rows.filter(row=>row[idKey]===uploaded.id);expect(added).toHaveLength(1);expect(added[0]).toMatchObject({accountId:target.accountId,mimeType:'image/jpeg',byteLength:uploaded.byteLength,sha256:uploaded.sha256,...(key==='media'?{purpose:'collection',status:'ready',originalFilename:'cropped-image.jpg',deletedAt:null}:{variant:'original',environment:'local',key:`local/${target.accountId}/${uploaded.id}`})});}
 expect(after.attachments).toEqual((before.attachments as Record<string,unknown>[]).map(row=>row.slot==='cover'&&row.guideId===target.id?{...row,mediaId:uploaded.id}:row));expect(guide.coverMediaId).toBe(uploaded.id);
}
