// Exact original-request custody for a single native transport failure. It makes
// no claim about a storage provider rejection.
function coverFailureCustody(page:Page,guideId:string){
 let original:Request|undefined,latched=false,failed=false,responded=false,coverPuts=0;const handlers:Promise<void>[]=[];let terminal!:()=>void;const done=new Promise<void>(resolve=>{terminal=resolve;});
 const isMedia=(request:Request)=>{const url=new URL(request.url());return url.origin===origin&&url.pathname===`${base}/media`&&request.method()==='POST'&&request.headers()['x-media-purpose']==='collection'&&request.headers()['x-file-name']==='cropped-image.jpg'&&request.headers()['content-type']==='image/jpeg';};
 const onRequest=(request:Request)=>{const url=new URL(request.url());if(url.origin===origin&&url.pathname===`${base}/collections/${guideId}/guide/cover`&&request.method()==='PUT')coverPuts++;};
 const onFailed=(request:Request)=>{if(request===original){failed=true;terminal();}};const onResponse=(response:Response)=>{if(response.request()===original){responded=true;terminal();}};
 const handler=(route:import('@playwright/test').Route)=>{const work=(async()=>{const request=route.request();if(latched||!isMedia(request)){await route.fallback();return;}latched=true;original=request;nativeCoverBytes(request);await route.abort('failed');})();handlers.push(work);void work.catch(()=>undefined);return work;};
 page.on('request',onRequest);page.on('requestfailed',onFailed);page.on('response',onResponse);
 return {handler,async settleHandlers(){await Promise.allSettled(handlers);},async settle(){await done;await Promise.all(handlers);expect(latched).toBe(true);expect(failed).toBe(true);expect(responded).toBe(false);expect(await original!.response()).toBeNull();expect(original!.failure()).not.toBeNull();expect(coverPuts).toBe(0);},async close(){terminal();const settled=await Promise.allSettled([done,...handlers]);page.off('request',onRequest);page.off('requestfailed',onFailed);page.off('response',onResponse);await page.unroute('**/api/explorers/v1/media',handler);expect(settled.every(result=>result.status==='fulfilled')).toBe(true);expect(coverPuts).toBe(0);}};
}
