function assertCoverCollectionAck(previous:typeof collectionCoreDtoSchema['_output'],command:{expectedRevision:number;title:string;description:string|null},actual:typeof collectionCoreDtoSchema['_output']){expect(command.expectedRevision).toBe(previous.revision);expect(actual).toEqual({...previous,title:command.title,description:command.description,revision:previous.revision+1});}
function coverResponseWaiters(page:Page,remaining:()=>number){
 const owned:Promise<Response>[]=[];
 return {original(method:string,path:string){const work=page.waitForResponse(r=>new URL(r.url()).origin===origin&&new URL(r.url()).pathname===path&&r.request().method()===method,{timeout:Math.max(1,remaining())});owned.push(work);void work.catch(()=>undefined);return work;},async finish(refused:boolean){if(refused)await page.close();let timer:ReturnType<typeof setTimeout>|undefined;try{const results=await Promise.race([Promise.allSettled(owned),new Promise<never>((_resolve,reject)=>{timer=setTimeout(()=>reject(Error('Guides cover waiters unsettled')),Math.max(1,remaining()));})]);if(!refused)expect(results.every(result=>result.status==='fulfilled')).toBe(true);return results.map(result=>result.status);}finally{if(timer)clearTimeout(timer);}}};
}

type PublicationCommand={expectedRevision:number;pinOrder?:number|null;visibility?:'public'|'private';publicationState?:'published'|'draft'};
function assertPublicationAck(previous:typeof collectionCoreDtoSchema['_output'],command:PublicationCommand,actual:typeof collectionCoreDtoSchema['_output']){
 expect(command.expectedRevision).toBe(previous.revision);const {expectedRevision:_revision,pinOrder:_pin,...fields}=command;expect(actual).toEqual({...previous,...fields,revision:previous.revision+1});
}
function assertPublicationScope(before:Observation,after:Observation,id:string,command:PublicationCommand){
 const target=before.guides.find(g=>g.id===id)!;expect(target).toBeDefined();expect(command.expectedRevision).toBe(target.revision);const categoryRevision=target.categoryContentRevision+1+(command.pinOrder!==undefined||target.pinOrder!==null&&(command.publicationState==='draft'||command.visibility==='private')?1:0);expect(after.guides).toEqual(before.guides.map(g=>({...g,...(g.id===id?{revision:g.revision+1,...(command.visibility!==undefined?{visibility:command.visibility}:{}),...(command.publicationState!==undefined?{publicationState:command.publicationState}:{}),...(command.publicationState==='draft'||command.visibility==='private'?{pinOrder:null}:command.pinOrder!==undefined?{pinOrder:command.pinOrder}:{})}:{}),categoryContentRevision:g.accountId===target.accountId?categoryRevision:g.categoryContentRevision})));
 for(const [key,p] of Object.entries(before.personas))expect(after.personas[key]).toEqual({...p,guidesContentRevision:p.accountId===target.accountId?categoryRevision:p.guidesContentRevision});for(const key of ['sections','media','objects','attachments'] as const)expect(after[key]).toEqual(before[key]);
}
function publicationMediaEligible(scope:{publicProfile:boolean;guidesPublic:boolean},guides:{id:string;visibility:string;publicationState:string;archivedAt:string|null}[],attachments:{mediaId:string;guideId:string}[],mediaId:string){return scope.publicProfile&&scope.guidesPublic&&attachments.some(a=>a.mediaId===mediaId&&guides.some(g=>g.id===a.guideId&&g.visibility==='public'&&g.publicationState==='published'&&g.archivedAt===null));}
function assertPublicationAccountAck(previous:typeof accountDtoSchema['_output'],command:typeof updateAccountRequestSchema['_output'],actual:typeof accountDtoSchema['_output']){expect(command.expectedRevision).toBe(previous.revision);const {expectedRevision:_revision,...fields}=command;expect(actual).toEqual({...previous,...fields,revision:previous.revision+1});}
function assertPublicationAccountScope(before:Observation,after:Observation,previous:typeof accountDtoSchema['_output'],actual:typeof accountDtoSchema['_output']){
 expect(after.guides).toEqual(before.guides);for(const [key,p] of Object.entries(before.personas))expect(after.personas[key]).toEqual(p.accountId===previous.id?{...p,accountRevision:actual.revision,publicProfile:actual.publicProfile,guidesPublic:actual.categories.find(c=>c.category==='guides')!.isPublic}:p);for(const key of ['sections','media','objects','attachments'] as const)expect(after[key]).toEqual(before[key]);
}
async function publicationCollection(request:APIRequestContext,id:string){return consume(await request.get(`${base}/collections/${id}`),async r=>{expect(r.status()).toBe(200);const {archived,displayOrder,...core}=ownerCollectionDtoSchema.parse((await r.json()).collection);expect(archived).toBe(false);expect(core.id).toBe(id);return collectionCoreDtoSchema.parse(core);});}
async function publicationAccount(request:APIRequestContext,id:string){return consume(await request.get(`${base}/me`),async r=>{expect(r.status()).toBe(200);const account=accountDtoSchema.parse((await r.json()).account);expect(account.id).toBe(id);return account;});}
async function publicationColdMedia(request:APIRequestContext,url:string,bytes:Buffer,eligible:boolean){
 const hash=createHash('sha256').update(bytes).digest('hex'),etag=`"${hash}"`;
 for(const variant of ['get','head','range','conditional'] as const){const headers:Record<string,string>=variant==='range'?{Range:'bytes=0-3'}:variant==='conditional'?{'If-None-Match':etag}:{};await consume(await request.fetch(url,{method:variant==='head'?'HEAD':'GET',headers}),async r=>{
  const body=await r.body(),h=r.headers();expect(h['x-content-type-options']).toBe('nosniff');
  if(eligible){expect(r.status()).toBe(variant==='range'?206:variant==='conditional'?304:200);expect(h.etag).toBe(etag);expect(h['cache-control']).toBe('public, max-age=300, must-revalidate');if(variant==='get'){expect(body).toEqual(bytes);expect(createHash('sha256').update(body).digest('hex')).toBe(hash);expect(h['content-length']).toBe(String(bytes.length));}else if(variant==='range'){expect(body).toEqual(bytes.subarray(0,4));expect(h['content-range']).toBe(`bytes 0-3/${bytes.length}`);expect(h['content-length']).toBe('4');}else {expect(body).toHaveLength(0);if(variant==='head')expect(h['content-length']).toBe(String(bytes.length));}
  }else{expect(r.status()).toBe(404);expect(h['cache-control']).toBe('no-store');expect(h.etag).toBeUndefined();expect(h['content-type']).not.toMatch(/image\//);expect(body.equals(bytes)).toBe(false);expect(body.includes(bytes.subarray(0,4))).toBe(false);if(variant==='head')expect(body).toHaveLength(0);else expect(JSON.parse(body.toString('utf8')).error).toMatchObject({code:'NOT_FOUND',message:'Media unavailable'});}
 });}
}
async function publicationOwnerMedia(request:APIRequestContext,url:string,bytes:Buffer,publicAttachment:boolean){await consume(await request.get(url),async r=>{expect(r.status()).toBe(200);expect(await r.body()).toEqual(bytes);expect(r.headers().etag).toBe(`"${createHash('sha256').update(bytes).digest('hex')}"`);expect(r.headers()['cache-control']).toBe(publicAttachment?'public, max-age=300, must-revalidate':'no-store');});}
// Own every original response waiter and body/finished producer until context closure.
function publicationCustody(page:Page,remaining:()=>number){
 const pending:Promise<unknown>[]=[];const own=<T>(work:Promise<T>)=>{pending.push(work);void work.catch(()=>undefined);return work;};
 return {own,original(method:string,path:string){return own(page.waitForResponse(r=>new URL(r.url()).origin===origin&&new URL(r.url()).pathname===path&&r.request().method()===method,{timeout:Math.max(1,remaining())}));},async finish(){let timer:ReturnType<typeof setTimeout>|undefined;try{const results=await Promise.race([Promise.allSettled(pending),new Promise<never>((_resolve,reject)=>{timer=setTimeout(()=>reject(Error('Guides publication custody unsettled')),Math.max(1,remaining()));})]);expect(results.every(r=>r.status==='fulfilled')).toBe(true);}finally{if(timer)clearTimeout(timer);}},async settleFailure(){let timer:ReturnType<typeof setTimeout>|undefined;try{await Promise.race([Promise.allSettled(pending),new Promise<never>((_resolve,reject)=>{timer=setTimeout(()=>reject(Error('Guides publication failure custody unsettled')),Math.max(1,remaining()));})]);}finally{if(timer)clearTimeout(timer);}}};
}
